    _PHASE_KEY = "phase"
    _BOOTSTRAP_PHASE = "bootstrap"
    _SNAPSHOT_ID_KEY = "snapshot_id"

    _UPSERT_OPERATION_TYPES = ["insert", "update", "replace"]
