    class MongoDBLakeflowConnect(LakeflowConnect):
        """LakeflowConnect implementation for MongoDB / MongoDB Atlas."""

        def __init__(self, options: dict[str, str]) -> None:
            """Initialise the connector.

            Args:
                options: Connection parameters:
                    - connection_uri: MongoDB connection string, e.g.
                      ``mongodb+srv://user:pass@cluster.mongodb.net`` (required).
                    - database: Name of the database to read from (required).

            Raises:
                ValueError: If a required parameter is missing.
            """
            super().__init__(options)

            self._connection_uri = options.get("connection_uri")
            if not self._connection_uri:
                raise ValueError("Missing required parameter 'connection_uri'")

            self._database = options.get("database")
            if not self._database:
                raise ValueError("Missing required parameter 'database'")

            # Cap the change-stream drain at init time so a single trigger only
            # emits events that existed when the connector started. The next
            # trigger builds a fresh instance with a newer cap and picks up the
            # rest, which is what makes CDC reads converge under
            # Trigger.AvailableNow.
            self._init_dt = datetime.now(timezone.utc)

        def _client(self) -> "MongoClient":
            """Create a new MongoClient.

            A fresh client is created per call rather than cached on the
            instance: Spark serialises the connector to ship it to executors,
            and a live ``MongoClient`` (which owns background threads and
            sockets) is not picklable. Callers own the returned client's
            lifecycle and must close it.
            """
            from pymongo import MongoClient

            return MongoClient(
                self._connection_uri,
                serverSelectionTimeoutMS=_SERVER_SELECTION_TIMEOUT_MS,
                connectTimeoutMS=_CONNECT_TIMEOUT_MS,
            )

        def list_tables(self) -> list[str]:
            """Return all user collections in the configured database."""
            client = self._client()
            try:
                db = client[self._database]
                return [
                    name
                    for name in db.list_collection_names()
                    if not name.startswith(_SYSTEM_COLLECTION_PREFIX)
                ]
            finally:
                client.close()

        def get_table_schema(self, table_name: str, table_options: dict[str, str]) -> StructType:
            """Return the envelope schema used by every collection."""
            self._validate_table(table_name)
            self._reject_removed_options(table_options)
            return StructType(
                [
                    StructField(_ID_FIELD, StringType(), False),
                    StructField(_DOCUMENT_FIELD, VariantType(), True),
                    StructField(_EVENT_TIME_FIELD, TimestampType(), False),
                    StructField(_DOCUMENT_HASH_FIELD, StringType(), True),
                ]
            )

        def read_table_metadata(self, table_name: str, table_options: dict[str, str]) -> dict:
            """Return change-stream metadata for every collection."""
            self._validate_table(table_name)
            self._reject_removed_options(table_options)
            return {
                "primary_keys": [_ID_FIELD],
                "cursor_field": _EVENT_TIME_FIELD,
                "ingestion_type": "cdc_with_deletes",
                "track_history_columns": [_DOCUMENT_HASH_FIELD],
            }

        def read_table(
            self, table_name: str, start_offset: dict, table_options: dict[str, str]
        ) -> tuple[Iterator[dict], dict]:
            """Read one change-stream upsert microbatch, or a bootstrap page."""
            self._validate_table(table_name)
            self._reject_removed_options(table_options)
            return self._read_change_stream(table_name, start_offset, table_options, for_deletes=False)

        def read_table_deletes(
            self, table_name: str, start_offset: dict, table_options: dict[str, str]
        ) -> tuple[Iterator[dict], dict]:
            """Read delete change-stream events for ``cdc_with_deletes``.

            Independent of ``read_table``: the framework checkpoints this flow
            with its own resume token.
            """
            self._validate_table(table_name)
            self._reject_removed_options(table_options)
            return self._read_change_stream(table_name, start_offset, table_options, for_deletes=True)

        def _read_change_stream(
            self,
            table_name: str,
            start_offset: dict,
            table_options: dict[str, str],
            for_deletes: bool,
        ) -> tuple[Iterator[dict], dict]:
            """Drain one change-stream microbatch, or bootstrap the collection.

            On the first upsert read (empty offset) a resume token is captured
            from ``watch()`` and the collection is dumped in ``_id`` pages.
            Later calls only watch. Deletes never dump. ``try_next`` returns
            ``None`` after ``max_await_time_ms`` with no event, which is what
            lets AvailableNow terminate instead of blocking forever on
            ``watch()``.
            """
            from pymongo.errors import OperationFailure, PyMongoError

            start_offset = start_offset or {}
            if self._is_bootstrap(start_offset, for_deletes):
                return self._bootstrap_change_stream(table_name, start_offset, table_options)

            max_records = self._resolve_max_records(table_options)
            batch_size = self._resolve_batch_size(table_options)
            operations = _DELETE_OPERATION_TYPES if for_deletes else _UPSERT_OPERATION_TYPES

            watch_kwargs: dict = {
                "pipeline": [{"$match": {"operationType": {"$in": operations}}}],
                "max_await_time_ms": _CHANGE_STREAM_MAX_AWAIT_MS,
            }
            if not for_deletes:
                watch_kwargs["full_document"] = "updateLookup"
            if batch_size:
                watch_kwargs["batch_size"] = batch_size

            token_str = start_offset.get(_RESUME_TOKEN_KEY)
            if token_str:
                watch_kwargs["resume_after"] = self._str_to_resume_token(token_str)
            else:
                watch_kwargs["start_at_operation_time"] = self._change_stream_start_timestamp()

            client = self._client()
            try:
                collection = client[self._database][table_name]
                try:
                    stream = collection.watch(**watch_kwargs)
                except OperationFailure as exc:
                    raise self._watch_failure(exc) from exc
                except PyMongoError as exc:
                    raise ValueError(f"MongoDB change stream failed: {exc}") from exc
                try:
                    return self._drain_change_stream(stream, start_offset, max_records, for_deletes)
                except PyMongoError as exc:
                    raise ValueError(
                        f"MongoDB change stream could not be resumed: {exc}. "
                        "If the resume token is stale, full-refresh the destination table."
                    ) from exc
                finally:
                    stream.close()
            finally:
                client.close()

        @staticmethod
        def _is_bootstrap(start_offset: dict, for_deletes: bool) -> bool:
            """True when the upsert path should dump the collection."""
            if for_deletes:
                return False
            if (start_offset or {}).get(_PHASE_KEY) == _BOOTSTRAP_PHASE:
                return True
            if start_offset.get(_RESUME_TOKEN_KEY):
                return False
            return True

        def _bootstrap_change_stream(
            self,
            table_name: str,
            start_offset: dict,
            table_options: dict[str, str],
        ) -> tuple[Iterator[dict], dict]:
            """Capture a resume token, then emit one page of the collection dump."""
            max_records = self._resolve_max_records(table_options)
            batch_size = self._resolve_batch_size(table_options)
            token_str = start_offset.get(_RESUME_TOKEN_KEY)
            snapshot_id = start_offset.get(_SNAPSHOT_ID_KEY)

            client = self._client()
            try:
                collection = client[self._database][table_name]
                if not token_str:
                    token_str = self._capture_resume_token(collection)
                records, last_id, exhausted = self._scan_bootstrap_page(
                    collection, snapshot_id, max_records, batch_size
                )
            finally:
                client.close()

            if not exhausted and last_id is not None:
                end_offset = {
                    _PHASE_KEY: _BOOTSTRAP_PHASE,
                    _RESUME_TOKEN_KEY: token_str,
                    _SNAPSHOT_ID_KEY: self._token_to_str(last_id),
                }
                return iter(records), end_offset
            return iter(records), {_RESUME_TOKEN_KEY: token_str}

        def _capture_resume_token(self, collection) -> str:
            """Open a watch, populate the post-batch token, then close it.

            The dump runs after this so updates during the scan are still in
            the oplog and are replayed once the offset becomes streaming-only.
            """
            from bson.timestamp import Timestamp
            from pymongo.errors import OperationFailure, PyMongoError

            watch_kwargs = {
                "pipeline": [{"$match": {"operationType": {"$in": _UPSERT_OPERATION_TYPES}}}],
                "max_await_time_ms": _CHANGE_STREAM_MAX_AWAIT_MS,
                "full_document": "updateLookup",
                "start_at_operation_time": Timestamp(int(self._init_dt.timestamp()), 1),
            }
            try:
                stream = collection.watch(**watch_kwargs)
            except OperationFailure as exc:
                raise self._watch_failure(exc) from exc
            except PyMongoError as exc:
                raise ValueError(f"MongoDB change stream failed: {exc}") from exc
            try:
                stream.try_next()
                token = stream.resume_token
            except PyMongoError as exc:
                raise ValueError(
                    f"MongoDB change stream could not be resumed: {exc}. "
                    "If the resume token is stale, full-refresh the destination table."
                ) from exc
            finally:
                stream.close()
            if token is None:
                raise ValueError(
                    "MongoDB did not return a change stream resume token. "
                    "Retry the pipeline; if it persists, the cluster may not "
                    "support change streams."
                )
            return self._token_to_str(token)

        def _scan_bootstrap_page(
            self,
            collection,
            snapshot_id: Optional[str],
            max_records: int,
            batch_size: int,
        ) -> tuple[list[dict], object, bool]:
            """Read one ``_id``-ordered page of the collection for bootstrap."""
            query: dict = {}
            if snapshot_id:
                query = {_ID_FIELD: {"$gt": self._str_to_resume_token(snapshot_id)}}
            db_cursor = collection.find(query).sort(_ID_FIELD, 1).limit(max_records)
            if batch_size:
                db_cursor = db_cursor.batch_size(batch_size)
            records: list[dict] = []
            last_id = None
            for document in db_cursor:
                records.append(self._document_to_record(document, self._init_dt))
                last_id = document[_ID_FIELD]
            exhausted = len(records) < max_records
            return records, last_id, exhausted

        def _drain_change_stream(
            self,
            stream,
            start_offset: dict,
            max_records: int,
            for_deletes: bool,
        ) -> tuple[Iterator[dict], dict]:
            """Consume events up to the init-time cap and ``max_records``."""
            records: list[dict] = []
            last_token = None
            while len(records) < max_records:
                event = stream.try_next()
                if event is None:
                    break
                operation = event.get("operationType")
                if operation in _INVALIDATING_OPERATION_TYPES:
                    raise ValueError(
                        f"MongoDB change stream was invalidated by {operation!r}. "
                        "The stream cannot be resumed; full-refresh the destination table."
                    )
                event_time = self._cluster_time_to_datetime(event.get("clusterTime"))
                if event_time is not None and event_time > self._init_dt:
                    break
                record = self._change_event_to_record(event, for_deletes)
                last_token = event.get("_id")
                if record is None:
                    continue
                records.append(record)

            if last_token is not None:
                end_offset = {_RESUME_TOKEN_KEY: self._token_to_str(last_token)}
            else:
                end_offset = start_offset or {}
            if not records:
                return iter([]), end_offset
            return iter(records), end_offset

        def _change_event_to_record(self, event: dict, for_deletes: bool) -> Optional[dict]:
            """Convert one change event into an envelope row, or skip it."""
            event_time = self._cluster_time_to_datetime(event.get("clusterTime"))
            if event_time is None:
                raise ValueError("Change stream event is missing clusterTime")
            if for_deletes:
                key = event.get("documentKey") or {}
                if _ID_FIELD not in key:
                    raise ValueError("Delete event is missing documentKey._id")
                return {
                    _ID_FIELD: str(key[_ID_FIELD]),
                    _DOCUMENT_FIELD: None,
                    _EVENT_TIME_FIELD: event_time,
                    _DOCUMENT_HASH_FIELD: None,
                }
            document = event.get("fullDocument")
            if not document:
                return None
            return self._document_to_record(document, event_time)

        def _document_to_record(self, document: dict, event_time: datetime) -> dict:
            """Convert a BSON document into an envelope record."""
            from bson import json_util

            if _ID_FIELD not in document:
                raise ValueError("Encountered a document without an '_id' field")
            # ``JSONOptions`` instances are not picklable, so the Relaxed options
            # are reached through the module at call time rather than bound to a
            # module-level constant that Spark would serialise with the connector.
            # The framework converts this Extended JSON string to VARIANT via
            # ``VariantVal.parseJson``. ``document_hash`` is the comparable
            # stand-in for SCD Type 2 (VARIANT cannot be compared with ``<=>``).
            payload = json_util.dumps(document, json_options=json_util.RELAXED_JSON_OPTIONS)
            return {
                _ID_FIELD: str(document[_ID_FIELD]),
                _DOCUMENT_FIELD: payload,
                _EVENT_TIME_FIELD: event_time,
                _DOCUMENT_HASH_FIELD: hashlib.sha256(payload.encode("utf-8")).hexdigest(),
            }

        def _change_stream_start_timestamp(self):
            """BSON Timestamp for the first watch when no resume token exists."""
            from bson.timestamp import Timestamp

            dt = self._init_dt
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return Timestamp(int(dt.timestamp()), 1)

        @staticmethod
        def _cluster_time_to_datetime(value) -> Optional[datetime]:
            """Convert a change-event ``clusterTime`` to UTC datetime."""
            from bson.timestamp import Timestamp

            if value is None:
                return None
            if isinstance(value, datetime):
                if value.tzinfo is None:
                    return value.replace(tzinfo=timezone.utc)
                return value.astimezone(timezone.utc)
            if isinstance(value, Timestamp):
                return datetime.fromtimestamp(value.time, tz=timezone.utc)
            return None

        @staticmethod
        def _token_to_str(token) -> str:
            """Serialise a resume token as Extended JSON."""
            from bson import json_util

            return json_util.dumps(token, json_options=json_util.RELAXED_JSON_OPTIONS)

        @staticmethod
        def _str_to_resume_token(value: str):
            """Parse a checkpointed resume token back to BSON."""
            from bson import json_util

            try:
                return json_util.loads(value, json_options=json_util.RELAXED_JSON_OPTIONS)
            except (TypeError, ValueError) as exc:
                raise ValueError(f"Invalid change-stream resume token: {value!r}") from exc

        @staticmethod
        def _watch_failure(exc: Exception) -> ValueError:
            """Map a failed ``watch()`` to an actionable ValueError."""
            message = str(exc)
            if "replica set" in message.lower() or getattr(exc, "code", None) == 40573:
                return ValueError(
                    "MongoDB change streams require a replica set or Atlas cluster. "
                    f"The server rejected watch(): {exc}"
                )
            return ValueError(
                f"MongoDB change stream could not be opened: {exc}. "
                "If the resume token is stale, full-refresh the destination table."
            )

        @staticmethod
        def _reject_removed_options(table_options: dict[str, str]) -> None:
            """Fail loudly if a retired table option is still set."""
            present = [name for name in _REMOVED_TABLE_OPTIONS if table_options.get(name)]
            if not present:
                return
            raise ValueError(
                "MongoDB table options "
                + ", ".join(repr(name) for name in present)
                + " are no longer supported. Every collection is ingested via "
                "change streams into `_id`, `document` (VARIANT), "
                "`event_time`, and `document_hash`. Remove the option(s) "
                "from table_configuration."
            )

        @staticmethod
        def _resolve_max_records(table_options: dict[str, str]) -> int:
            """Parse the optional ``max_records_per_batch`` table option."""
            raw = table_options.get("max_records_per_batch")
            if raw is None or str(raw).strip() == "":
                return _DEFAULT_MAX_RECORDS_PER_BATCH
            try:
                value = int(raw)
            except (TypeError, ValueError) as exc:
                raise ValueError(f"Invalid 'max_records_per_batch' option: {raw!r}") from exc
            if value <= 0:
                raise ValueError(f"'max_records_per_batch' must be positive, got {value}")
            return value

        @staticmethod
        def _resolve_batch_size(table_options: dict[str, str]) -> int:
            """Parse the optional ``batch_size`` table option (0 = driver default)."""
            raw = table_options.get("batch_size")
            if raw is None or str(raw).strip() == "":
                return 0
            try:
                value = int(raw)
            except (TypeError, ValueError) as exc:
                raise ValueError(f"Invalid 'batch_size' option: {raw!r}") from exc
            if value < 0:
                raise ValueError(f"'batch_size' must be non-negative, got {value}")
            return value

        def _validate_table(self, table_name: str) -> None:
            supported = self.list_tables()
            if table_name not in supported:
                raise ValueError(f"Collection '{table_name}' not found. Available: {supported}")


    ########################################################
    # src/databricks/labs/community_connector/sparkpds/lakeflow_datasource.py
    ########################################################

    LakeflowConnectImpl = MongoDBLakeflowConnect
    # Constant option or column names
    METADATA_TABLE = "_community_table_metadata"
    NAMESPACES_TABLE = "_community_namespaces"
    TABLES_TABLE = "_community_tables"
    VIRTUAL_TABLES = (METADATA_TABLE, NAMESPACES_TABLE, TABLES_TABLE)
    TABLE_NAME = "tableName"
    TABLE_NAME_LIST = "tableNameList"
    TABLE_CONFIGS = "tableConfigs"
    IS_DELETE_FLOW = "isDeleteFlow"
    NAMESPACE_PREFIX = "namespacePrefix"
    NAMESPACE = "namespace"


    def _decode_list_of_str_option(option_name: str, value: str | None) -> list[str] | None:
        """Decode and validate a JSON-encoded ``list[str]`` Spark option.

        Returns ``None`` if the option is absent; otherwise the parsed list.
        Raises ``ValueError`` with the offending value if the JSON is malformed
        or the decoded value is not a list of strings.
        """
        if value is None:
            return None
        try:
            decoded = json.loads(value)
        except json.JSONDecodeError as e:
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded list[str]; "
                f"got non-JSON value: {value!r}"
            ) from e
        if not isinstance(decoded, list) or not all(isinstance(s, str) for s in decoded):
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded list[str]; got: {decoded!r}"
            )
        return decoded


    def _decode_dict_option(option_name: str, value: str | None) -> dict:
        """Decode and validate a JSON-encoded ``dict`` Spark option."""
        if value is None:
            return {}
        try:
            decoded = json.loads(value)
        except json.JSONDecodeError as e:
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded dict; got non-JSON value: {value!r}"
            ) from e
        if not isinstance(decoded, dict):
            raise ValueError(f"option '{option_name}' must be a JSON-encoded dict; got: {decoded!r}")
        return decoded


    # PySpark's DataSource API requires camelCase method names and inherits
    # semantics from the parent class, so per-method docstrings are redundant.
    # pylint: disable=invalid-name,missing-function-docstring
    class LakeflowStreamReader(SimpleDataSourceStreamReader, SupportsTriggerAvailableNow):
        """
        Implements a data source stream reader for Lakeflow Connect.
        Currently, only the simpleStreamReader is implemented, which uses a
        more generic protocol suitable for most data sources that support
        incremental loading.
        """

        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.lakeflow_connect = lakeflow_connect
            self.schema = schema

        def initialOffset(self):
            return {}

        def read(self, start: dict) -> (Iterator[tuple], dict):
            is_delete_flow = self.options.get(IS_DELETE_FLOW) == "true"
            # Strip delete flow options before passing to connector
            table_options = {k: v for k, v in self.options.items() if k != IS_DELETE_FLOW}

            if is_delete_flow:
                records, offset = self.lakeflow_connect.read_table_deletes(
                    self.options[TABLE_NAME], start, table_options
                )
            else:
                records, offset = self.lakeflow_connect.read_table(
                    self.options[TABLE_NAME], start, table_options
                )
            rows = map(lambda x: parse_value(x, self.schema), records)
            return rows, offset

        def readBetweenOffsets(self, start: dict, end: dict) -> Iterator[tuple]:
            # TODO: This does not ensure the records returned are identical across repeated calls.
            # For append-only tables, the data source must guarantee that reading from the same
            # start offset will always yield the same set of records.
            # For tables ingested as incremental CDC, it is only necessary that no new changes
            # are missed in the returned records.
            return self.read(start)[0]

        def prepareForTriggerAvailableNow(self) -> None:
            # No need to do anything special here. Everything is handled in the __init__ method.
            pass


    class LakeflowPartitionedStreamReader(DataSourceStreamReader, SupportsTriggerAvailableNow):
        """Proxy that bridges SupportsPartitionedStream to PySpark's DataSourceStreamReader.

        Used when a connector implements the SupportsPartitionedStream mixin to
        support partitioned streaming reads across Spark executors.
        """

        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.schema = schema
            self.lakeflow_connect = lakeflow_connect
            self.table_name = options[TABLE_NAME]
            self.table_options = {k: v for k, v in options.items() if k != IS_DELETE_FLOW}

        def initialOffset(self):
            return {}

        def getDefaultReadLimit(self):
            # Admission control is the connector's responsibility (e.g. via
            # window_days, max_records_per_batch), not the engine's.  Always
            # ask the engine for ReadAllAvailable.
            return ReadAllAvailable()

        def latestOffset(self, start: dict, limit) -> dict:
            # We declared ReadAllAvailable via getDefaultReadLimit; the engine
            # must respect it.  Anything else means admission-control expectations
            # we do not support — fail loudly rather than silently ignore.
            if not isinstance(limit, ReadAllAvailable):
                raise ValueError(
                    f"LakeflowPartitionedStreamReader only supports ReadAllAvailable; "
                    f"got {type(limit).__name__}. Micro-batch sizing must be controlled "
                    f"by the connector implementation (table_options), not the engine."
                )
            return self.lakeflow_connect.latest_offset(self.table_name, self.table_options, start)

        def partitions(self, start: dict, end: dict):
            partition_descs = self.lakeflow_connect.get_partitions(
                self.table_name, self.table_options, start, end
            )
            return [InputPartition(json.dumps(p)) for p in partition_descs]

        def read(self, partition: InputPartition):
            partition_desc = json.loads(partition.value)
            records = self.lakeflow_connect.read_partition(
                self.table_name, partition_desc, self.table_options
            )
            return map(lambda x: parse_value(x, self.schema), records)

        def prepareForTriggerAvailableNow(self) -> None:
            # No need to do anything special here. Everything is handled in the __init__ method.
            pass


    class LakeflowBatchReader(DataSourceReader):
        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.schema = schema
            self.lakeflow_connect = lakeflow_connect
            self.table_name = options[TABLE_NAME]
            self._supports_partition = isinstance(lakeflow_connect, SupportsPartition)

        def partitions(self):
            if self._supports_partition and self.table_name not in VIRTUAL_TABLES:
                try:
                    partition_descs = self.lakeflow_connect.get_partitions(
                        self.table_name, self.options
                    )
                    return [InputPartition(json.dumps(p)) for p in partition_descs]
                except Exception:
                    self._supports_partition = False
            return [InputPartition(None)]

        def read(self, partition):
            if self.table_name == METADATA_TABLE:
                records = self._read_table_metadata()
            elif self.table_name == NAMESPACES_TABLE:
                records = self._read_namespaces()
            elif self.table_name == TABLES_TABLE:
                records = self._read_tables()
            elif self._supports_partition and partition.value is not None:
                partition_desc = json.loads(partition.value)
                records = self.lakeflow_connect.read_partition(
                    self.table_name, partition_desc, self.options
                )
            else:
                records, _ = self.lakeflow_connect.read_table(self.table_name, None, self.options)
            return map(lambda x: parse_value(x, self.schema), records)

        def _read_table_metadata(self):
            table_names = (
                _decode_list_of_str_option(TABLE_NAME_LIST, self.options.get(TABLE_NAME_LIST)) or []
            )
            table_configs = _decode_dict_option(TABLE_CONFIGS, self.options.get(TABLE_CONFIGS))
            all_records = []
            # Preserve caller-supplied table order — caller controls it.
            for table in table_names:
                metadata = self.lakeflow_connect.read_table_metadata(
                    table, table_configs.get(table, {})
                )
                all_records.append({TABLE_NAME: table, **metadata})
            return all_records

        def _read_namespaces(self):
            # Connectors without SupportsNamespaces are flat — no rows.
            if not isinstance(self.lakeflow_connect, SupportsNamespaces):
                return []
            prefix = _decode_list_of_str_option(NAMESPACE_PREFIX, self.options.get(NAMESPACE_PREFIX))
            namespaces = self.lakeflow_connect.list_namespaces(prefix)
            # Sort framework-side for deterministic output regardless of
            # connector iteration order.
            return [{"namespace": ns} for ns in sorted(namespaces)]

        def _read_tables(self):
            namespace_supplied = NAMESPACE in self.options
            if isinstance(self.lakeflow_connect, SupportsNamespaces):
                if not namespace_supplied:
                    raise ValueError(
                        f"option '{NAMESPACE}' is required when reading "
                        f"'{TABLES_TABLE}' against a connector that implements "
                        f"SupportsNamespaces. Pass a JSON-encoded list[str] "
                        f"(use '[]' for root-level tables; walk the tree via "
                        f"'{NAMESPACES_TABLE}' to enumerate every namespace)."
                    )
                namespace = _decode_list_of_str_option(NAMESPACE, self.options[NAMESPACE])
                tables = self.lakeflow_connect.list_tables_in_namespace(namespace)
                return [{"namespace": namespace, TABLE_NAME: tn} for tn in sorted(tables)]
            # Flat connector path. Reject a stray `namespace` option — the
            # caller probably mistook this connector for namespace-aware and
            # silently ignoring the option would mask the bug.
            if namespace_supplied:
                raise ValueError(
                    f"option '{NAMESPACE}' was supplied but the connector does "
                    f"not implement SupportsNamespaces. Either omit the option "
                    f"or use a namespace-aware connector."
                )
            return [
                {"namespace": [], TABLE_NAME: tn} for tn in sorted(self.lakeflow_connect.list_tables())
            ]


    class LakeflowSource(DataSource):
        """
        PySpark DataSource base for Lakeflow Connect.

        Two ways the connector implementation is bound:

        - Per-source subclass (wheel / multi-file deployment): subclass and set
          ``_lakeflow_connect_cls``::

              class GmailDataSource(LakeflowSource):
                  _lakeflow_connect_cls = GmailLakeflowConnect

              spark.dataSource.register(GmailDataSource)

        - Merged single-file deployment (SDP): ``_lakeflow_connect_cls`` is left
          ``None`` and the connector is taken from the module-level
          ``LakeflowConnectImpl`` placeholder, which the merge script substitutes
          with the actual implementation class.
        """

        # Per-source subclasses set this. Left ``None`` on the base so the merged
        # single-file path falls back to the ``LakeflowConnectImpl`` placeholder.
        _lakeflow_connect_cls = None

        # Spark format name. Defaults to "lakeflow_connect" because Unity Catalog
        # connection-option injection looks for that exact string. A per-source
        # subclass may override this with its source name once it no longer relies
        # on UC injection (see the commented override in each source's __init__.py).
        _format_name = "lakeflow_connect"

        def __init__(self, options):
            self.options = options
            table = options.get(TABLE_NAME)
            # Catch typos against the framework's reserved virtual-table namespace
            # early — falling through to the connector with an unknown
            # `_community_*` name yields a confusing per-connector error.
            if table and table.startswith("_community_") and table not in VIRTUAL_TABLES:
                raise ValueError(
                    f"unknown framework virtual table '{table}'. Valid framework "
                    f"virtual tables are: {', '.join(VIRTUAL_TABLES)}. "
                    f"For a regular source table, use a name that does not start "
                    f"with '_community_'."
                )
            # Per-source subclasses bind the implementation via _lakeflow_connect_cls.
            # The merged single-file path leaves it None and relies on the
            # LakeflowConnectImpl placeholder (substituted by the merge script).
            connect_cls = type(self)._lakeflow_connect_cls or LakeflowConnectImpl
            self.lakeflow_connect = connect_cls(options)  # pylint: disable=abstract-class-instantiated

        @classmethod
        def name(cls):
            return cls._format_name

        def schema(self):
            table = self.options[TABLE_NAME]
            if table == METADATA_TABLE:
                return StructType(
                    [
                        StructField(TABLE_NAME, StringType(), False),
                        StructField("primary_keys", ArrayType(StringType()), True),
                        StructField("cursor_field", StringType(), True),
                        StructField("ingestion_type", StringType(), True),
                        StructField("track_history_columns", ArrayType(StringType()), True),
                    ]
                )
            if table == NAMESPACES_TABLE:
                return StructType(
                    [
                        StructField("namespace", ArrayType(StringType()), False),
                    ]
                )
            if table == TABLES_TABLE:
                return StructType(
                    [
                        StructField("namespace", ArrayType(StringType()), False),
                        StructField(TABLE_NAME, StringType(), False),
                    ]
                )
            return self.lakeflow_connect.get_table_schema(table, self.options)

        def reader(self, schema: StructType):
            return LakeflowBatchReader(self.options, schema, self.lakeflow_connect)

        def streamReader(self, schema: StructType):
            # Use the partitioned DataSourceStreamReader when the connector
            # implements SupportsPartitionedStream and the table opts in.
            # Otherwise, delegate to super() which raises PySparkNotImplementedError,
            # causing Spark to fall back to simpleStreamReader().
            if isinstance(self.lakeflow_connect, SupportsPartitionedStream):
                table = self.options[TABLE_NAME]
                if self.lakeflow_connect.is_partitioned(table):
                    return LakeflowPartitionedStreamReader(self.options, schema, self.lakeflow_connect)
            return super().streamReader(schema)

        def simpleStreamReader(self, schema: StructType):
            return LakeflowStreamReader(self.options, schema, self.lakeflow_connect)


    spark.dataSource.register(LakeflowSource)
